require __DIR__.'/bootstrap.php';require __DIR__.'/editor.php';$user=require_user();$site=site_by_owner((int)$user['id']);if(!$site)exit('Site introuvable.');$csrf=csrf_token();$error='';$article=['title'=>'','excerpt'=>'','content'=>'','category'=>'Développement','tags'=>'','image'=>'assets/images/blog-default.svg','status'=>'draft','featured'=>0,'seo_title'=>'','seo_description'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){if(is_read_only_demo())$error='La démo publique est en lecture seule.';else{verify_csrf();foreach(['title','excerpt','content','category','tags','seo_title','seo_description','status'] as $key)$article[$key]=trim((string)($_POST[$key]??$article[$key]));$article['featured']=isset($_POST['featured'])?1:0;if($article['title']===''||$article['content']==='')$error='Titre et contenu requis.';else{try{$builtin=trim((string)($_POST['builtin_image']??''));$imageBase=$builtin!==''?$builtin:trim((string)($_POST['image_url']??''));$article['image']=normalize_image_input($imageBase,$_FILES['image']??null,'assets/images/blog-default.svg');$now=now_iso();$status=$article['status']==='published'?'published':'draft';$s=db()->prepare('INSERT INTO articles (site_id,author_id,title,slug,excerpt,content,category,tags,image,status,featured,seo_title,seo_description,created_at,updated_at,published_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([(int)$site['id'],(int)$user['id'],$article['title'],unique_article_slug(db(),(int)$site['id'],$article['title']),$article['excerpt'],$article['content'],$article['category'],$article['tags'],$article['image'],$status,$article['featured'],$article['seo_title'],$article['seo_description'],$now,$now,$status==='published'?$now:null]);redirect('admin.php');}catch(Throwable $e){$error=$e->getMessage();}}}}
render_header('Nouvel article','Créez une publication.','dashboard-body editor-page');?>
